INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1, "ねぇねぇ、騎士クン\n手伝ってあげようよ～", 0, "ヒヨリでっす♪\n元気いっぱいがんばるよ♪", 1.4, "春咲 ひより", "お！\nあそこに困ってそうな人発見！", 0, 1, 1, 0, 1001, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1, "わ、わたし、\nなに言ってるんだろ\nあはは…", 0, "みんなみたいに\nわたしも強くならなきゃ", 1.4, "草野 優衣", "大切な人を\n守れるようになりたい…って", 0, 1, 1, 0, 1002, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1, "少しは磨かれると思いますよ。", 0, "フェンシングを始めてみては？", 1.4, "士条 怜", "キミに必要な集中力と感性が", 0, 1, 1, 0, 1003, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1, "みそぎはねぇ、\nかくれんぼやりたい！", 0, "ねぇ、にいちゃん！", 1.5, "穂高 みそぎ", "今日はなにして遊ぶ？", 0, 1, 1, 0, 1004, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1, "私といっしょに…\nいかない？", 0, "風宮あかりです", 1.4, "風宮 あかり", "ねぇ…", 0, 1, 1, 0, 1006, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1, "食べ物の恨みは怖いのー", 0, "出雲宮子なのー", 1.5, "出雲 宮子", "プリンたべたいのー", 0, 1, 1, 0, 1007, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1, "いいよ。\n見られることは運命さ…", 0, "ボクは虹村雪。", 1.4, "虹村 雪", "キミもボクの美貌に\n吸い寄せられたんだね。", 0, 1, 1, 0, 1008, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1, "人呼んで「疾風の冥姫」!!", 0, "フッ…聞いて後悔するがいい！", 1.4, "柊杏奈", "我が真名は\nアンネローゼ・フォン・シュテッヒパルム！", 0, 1, 1, 0, 1009, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1, "ほんまおおきにやわ～♪", 0, "マホマホ王国のプリンセス、\nまほ姫どす", 1.5, "姫宮 真歩", "うさぎさん、\n運命の王子はんに巡りあわせてくれて", 0, 1, 1, 0, 1010, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1, "ここで会ったが\n100年目～！", 0, "衣之咲璃乃です！", 1.4, "衣之咲 璃乃", "生き別れたお兄ちゃんを探して\n三千世界！", 0, 1, 1, 0, 1011, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1, "…って、お願い！\n誰にも言わないでおいて～！", 0, "私はハツネ、\n結構強いんだよ。\nきらーん☆", 1.4, "柏崎 初音", "ち、超能力って…\n何のことかな～？", 0, 1, 1, 0, 1012, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1, "ヒデサイまぢ\nGF（グッドフィーリング）～♪", 0, "ちょす！\n美波鈴奈だよ～♪", 1.4, "美波 鈴奈", "一応カリスマ読モJKやってまっす！", 0, 1, 1, 0, 1016, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1, "でも、沖縄もとってもいいとこさー", 0, "はいたーい。\n喜屋武香織さー。", 1.4, "喜屋武 香織", "東京は遊園地みたいなところさー", 0, 1, 1, 0, 1017, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1, "イオちゃんって呼んでね。", 0, "支倉伊緒です。", 1.4, "支倉 伊緒", "先生って呼ばれるのは\nくすぐったいから", 0, 1, 1, 0, 1018, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1, "ミミをおいてかないでぇ～", 0, "ふえ…？\nミミ、むずかしいこと\nよくわかんない…", 1.5, "茜 ミミ", "あ！/\お兄ちゃ～ん\nまってよ～", 0, 1, 1, 0, 1020, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1, "ふぇぇぇぇぇん……", 0, "あ…あの…えっと…\n栗…林…くるみ…です……", 1.5, "栗林 くるみ", "あの……\nふぇ……", 0, 1, 1, 0, 1021, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1, "なんてありがとうございます！", 0, "風宮よりです。\nあああああ！", 1.4, "風宮 より", "こんな私に貴重な時間を\n割いていただき、", 0, 1, 1, 0, 1022, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1, "私こっち行きたいー\nね、早く早くー", 0, "私、アヤネ！\nぷうきちと一緒についてってあげるね！", 1.5, "北条 綾音", "おにいちゃんどこいくの？\nえ？", 0, 1, 1, 0, 1023, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1, "これて何か違う…\nあああすみません！", 0, "わっ…わっ…私、\n天野すずめといいます！", 1.4, "天野 すずめ", "ふ、不束者ですが\nどうぞ末永く…って、", 0, 1, 1, 0, 1025, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1, "離しませんわ………\n絶対に…!!", 0, "……クスクス…私は\n…倉石恵理子……", 1.4, "倉石 恵理子", "あなたは…運命の……\n伴侶……", 0, 1, 1, 0, 1027, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1, "…そうでしょ？？", 0, "佐々木咲恋よ。\nねえ、世の中に無駄なことが\n多すぎると思わない？", 1.4, "佐々木 咲恋", "その無駄を省くことができれば、\nもっと余裕のある暮らしができるっ！", 0, 1, 1, 0, 1028, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1, "あはは、\n私もまだまだだなぁ～", 0, "桜井望だよ！\nよろしくねっ", 1.4, "桜井 望", "ぇっと…\nキミ、私のこと知らないの?!", 0, 1, 1, 0, 1029, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1, "ショーグン、\nワタシと一緒に天下統一デース！", 0, "デケデケデンっ！", 1.4, "ニノン・ジュベール", "初めまして、\n私はニノン・ジュベール申すデス！", 0, 1, 1, 0, 1030, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1, "おかしいですね……", 0, "上喜しのぶです。\n手元のドクロが父です。", 1.4, "上喜 しのぶ", "でもって私の隣にいるのが……\nえ、見えない？", 0, 1, 1, 0, 1031, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1, "そう、\nオラのボケに突っ込める相方が…！", 0, "目指すはビッグな\nお笑い芸人だっぺ！", 1.5, "野戸まひる", "けんども\nそれには足りないモンが…", 0, 1, 1, 0, 1033, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1, "ちょ\nちょっと一杯飲んできます…！", 0, "あの…私…綾瀬ゆかりです…\nあの…ごめんなさい！", 1.4, "綾瀬 ゆかり", "ちょっと緊張しちゃって…", 0, 1, 1, 0, 1034, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1, "これ以上お話しすることは…\nないです！", 0, "氷川鏡華…です", 1.5, "氷川 鏡華", "知らない人とは話しちゃいけないので", 0, 1, 1, 0, 1036, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1, "私体が弱いから、\n30分に一度休憩しないと\nいけないんです。", 0, "柏崎…栞です。", 1.4, "柏崎 栞", "……あ、アラーム。", 0, 1, 1, 0, 1038, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1, "野に咲く花が、\n唯一の話相手です。", 0, "ふ、双葉碧です。", 1.4, "双葉 碧", "私、一人も友達がいなくて……", 0, 1, 1, 0, 1040, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1, "そう思っています。", 0, "三角千歌です。", 1.4, "三角 千歌", "私の歌声で、\n皆さんが幸せになってくれたらいいなって…", 0, 1, 1, 0, 1042, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1, "う、疑ってすまなかったな…", 0, "安芸真琴だ。", 1.4, "安芸 真琴", "あぁ？\nお前のそいつの仲間か？", 0, 1, 1, 0, 1043, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1, "わらわの偉大な力に\nひれ伏すがいい！\nはっはっは！", 0, "わらわこそは夜を総べる者！", 1.4, "イリヤ・オーンスタイン", "生けとし生ける全ての者よ！", 0, 1, 1, 0, 1044, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1, "ｌク、クウカに何かご用ですか!?", 0, "そこで騎士は妖精を乱暴に……", 1.4, "遠見 空花", "ぐふふふふ……はっ！", 0, 1, 1, 0, 1045, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1, "う～ん…\n猫ってホントに最高にゃ～♪", 0, "宮坂たまきにゃ♪\n猫はいいにゃよ？", 1.4, "宮坂たまき", "自由気ままで♪\n寝て遊んで、食べてケンカして…", 0, 1, 1, 0, 1046, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1, "…と思ったら\nバイトの時間だ！\nまたあとでね！", 0, "大神美冬よ！", 1.4, "大神 美冬", "それでは早速クエストに…", 0, 1, 1, 0, 1048, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1, "お姉ちゃんがぜ～んぶ\nやってあげるからね！", 0, "星野静流だよ！", 1.4, "星野静流", "クエストもバトルも\n掃除も洗濯も", 0, 1, 1, 0, 1049, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1, "学校では誰もが憧れる\nアイドル的な存在ってやつよ♪", 0, "アタシは玉泉美咲。", 1.5, "玉泉美咲", "見ての通りの\nセクシー美少女で", 0, 1, 1, 0, 1050, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1, "？？？？", 0, "？？？", 1.4, "リマ", "？？？？", 0, 1, 1, 0, 1052, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1, "そ、そこまでいうなら\nもらってやる", 0, "モニカ・ヴァイスヴィントだ。", 1.5, "モニカ・ヴァイスヴィント", "菓子でつろうなどと\n稚拙な策を……", 0, 1, 1, 0, 1053, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1, "そ、そこまでいうなら\nもらってやる", 0, "モニカ・ヴァイスヴィントだ。", 1.5, "ペコリーヌ", "菓子でつろうなどと\n稚拙な策を……", 0, 1, 1, 0, 1058, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1, "そ、そこまでいうなら\nもらってやる", 0, "モニカ・ヴァイスヴィントだ。", 1.5, "コッコロ", "菓子でつろうなどと\n稚拙な策を……", 0, 1, 1, 0, 1059, 0);
INSERT INTO `v1_1c1dce3dab4cb964d367db3f6a9812d332cd98321b883e14915b5b446a10af32` VALUES (0, 2, 1, "そ、そこまでいうなら\nもらってやる", 0, "モニカ・ヴァイスヴィントだ。", 1.5, "キャル", "菓子でつろうなどと\n稚拙な策を……", 0, 1, 1, 0, 1060, 0);
